"use client";
import { useMorph } from "@/lib/cojeev-motion/use-morph";
import * as React from "react";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Button, type ButtonProps } from "@/components/ui/button";
import {
  InputControl,
  type InputControlProps,
} from "@/components/ui/input";
import { Textarea, type TextareaProps } from "@/components/ui/textarea";
export const inputGroupVariants = cva(
  "v-igroup flex items-center h-[52px] gap-[10px] py-0 pl-[18px] pr-[6px] rounded-[var(--r-pill)] [border:0] bg-[var(--input)] [box-shadow:inset_0_0_0_1px_var(--v-edge)]",
);
export type InputGroupProps = React.ComponentProps<"div">;
export function InputGroup({ref: externalMorphRef,  className, ...props }: InputGroupProps) {
  const ownedMorphRef = useMorph<HTMLDivElement>("inputs", externalMorphRef);
  return (
    <div ref={ownedMorphRef}
      data-slot="input-group"
      data-part="root"
      className={cn(inputGroupVariants(), className)}
      {...props}
    />
  );
}
export type InputGroupAddonProps = React.ComponentProps<"div">;
export function InputGroupAddon({ className, ...props }: InputGroupAddonProps) {
  return (
    <div
      data-slot="input-group-addon"
      data-part="addon"
      className={cn(
        "v-addon shrink-0 whitespace-nowrap text-[13px] font-medium text-[color:var(--v-text-2)]",
        className,
      )}
      {...props}
    />
  );
}
export type InputGroupInputProps = InputControlProps;
export function InputGroupInput({ className, ...props }: InputGroupInputProps) {
  return (
    <InputControl
      data-slot="input-group-input"
      className={cn(
        "text-[length:var(--fs-body)] text-[color:var(--v-text)]",
        className,
      )}
      {...props}
    />
  );
}
export type InputGroupTextareaProps = TextareaProps;
export function InputGroupTextarea(props: InputGroupTextareaProps) {
  return <Textarea data-slot="input-group-textarea" {...props} />;
}
export type InputGroupButtonProps = ButtonProps;
export function InputGroupButton({
  className,
  ...props
}: InputGroupButtonProps) {
  return (
    <Button
      data-slot="input-group-button"
      className={cn("h-[40px] px-[16px] shrink-0", className)}
      {...props}
    />
  );
}
export type InputGroupTextProps = React.ComponentProps<"span">;
export function InputGroupText({ className, ...props }: InputGroupTextProps) {
  return (
    <span
      data-slot="input-group-text"
      className={cn("text-[13px] text-[color:var(--v-text-2)]", className)}
      {...props}
    />
  );
}
export type InputSearchProps = React.ComponentProps<"div">;
export function InputSearch({ className, ...props }: InputSearchProps) {
  return (
    <div
      data-slot="input-search"
      className={cn("v-search flex items-center gap-[12px]", className)}
      {...props}
    />
  );
}
export type InputSearchScopeProps = React.ComponentProps<"div">;
export function InputSearchScope({
  className,
  ...props
}: InputSearchScopeProps) {
  return (
    <div
      data-slot="input-search-scope"
      className={cn(
        "v-scope flex shrink-0 items-center gap-[6px] text-[12.5px] text-[color:var(--v-text-2)] whitespace-nowrap",
        className,
      )}
      {...props}
    />
  );
}

export type InputSearchDiskProps=React.ComponentProps<"span">;
export function InputSearchDisk({ref,className,...props}:InputSearchDiskProps){
  const ownedRef=useMorph<HTMLSpanElement>("icons",ref);
  return <span ref={ownedRef} data-slot="input-search-disk" data-part="icon" className={cn("v-search__disk grid place-items-center shrink-0 size-[36px] [border-radius:50%] bg-[var(--v-pink)] text-[color:var(--v-on-accent)]",className)} {...props}/>;
}

@layer cojeev-states {
[data-slot="input-group"] {
  transition:
    background var(--t-micro),
    box-shadow var(--t-micro);
}
[data-slot="input-group"]:focus-within {
  background: var(--v-pink-soft);
  box-shadow: inset 0 0 0 2px var(--v-brand);
}
[data-slot="input-group"] > .v-icon {
  width: 18px;
  height: 18px;
  color: var(--v-text-2);
  flex: none;
}
[data-slot="input-group"] .v-badge {
  height: 26px;
  background: var(--v-canvas);
  box-shadow: inset 0 0 0 1px var(--v-border);
  color: var(--v-text);
  flex: none;
}
[data-slot="input-group"] .v-badge.-ink {
  background: var(--v-ink);
  color: var(--v-on-ink);
  box-shadow: none;
}
[data-slot="input-group"] .v-badge.-dashed {
  background: transparent;
}
[data-slot="input-group"] .v-btn {
  height: 40px;
  padding: 0 16px;
  flex: none;
}
[data-slot="input-group"] .v-ibtn[data-slot] {
  width: 40px;
  height: 40px;
  flex: none;
}
[data-slot="input-group"] .v-sep.-v[data-slot] {
  height: 24px;
  margin: 0 2px;
  background: var(--v-edge);
  opacity: 0.5;
}
[data-slot="input-search"] .v-input {
  height: 36px;
  font-size: var(--fs-control);
  min-width: 0;
  border-color: var(--v-border);
  box-shadow: inset 0 0 0 1px var(--v-border);
  background: var(--v-canvas);
}
[data-slot="input-search"] .v-input:focus-within {
  box-shadow: inset 0 0 0 2px var(--v-brand);
  background: var(--v-canvas);
}
[data-slot="input-search"] .v-search__disk {
  width: 36px;
  height: 36px;
  flex: none;
}
[data-slot="input-search-scope"] .v-badge {
  height: 24px;
  font-size: 11.5px;
  padding: 0 9px;
}
[data-slot="input-search"] [data-slot="input-search-scope"] .v-badge.-dashed {
  height: 26px;
  background: transparent;
  border-color: var(--v-border);
  color: var(--v-text-2);
}
:root[data-mode="dark"] [data-slot="input-group"] {
  background: var(--v-beige);
  box-shadow: inset 0 0 0 1px var(--v-border);
}
:root[data-mode="dark"] [data-slot="input-group"]:focus-within {
  background: color-mix(in oklab, var(--v-pink) 14%, var(--v-canvas));
  box-shadow: inset 0 0 0 2px var(--v-pink);
}
:root[data-mode="dark"] [data-slot="input-group"] .v-badge {
  background: var(--v-beige-2);
  box-shadow: inset 0 0 0 1px var(--v-border);
}

[data-slot="input-search"] { flex: 1; min-width: 0; }
[data-slot="input-search-scope"] { font-size: 13px; color: var(--v-text); min-width: 0; flex-wrap: wrap; }
[data-slot="input-search"] .v-input input { flex: 1 1 60px; min-width: 0; }
@media (max-width: 640px) { [data-slot="input-search"] [data-slot="input-search-scope"] { display: none; } }
[data-slot="input-group"] { min-width:0; min-height:52px; height:auto; padding-block:6px; }
[data-slot="input-group"] [data-slot="input-group-input"] { min-height:40px; width:0; flex:1 1 80px; }
[data-slot="input-group-addon"] { min-width:0; max-width:45%; white-space:normal; overflow-wrap:anywhere; }
[data-slot="input-group-text"] { min-width:0; max-width:100%; overflow-wrap:anywhere; }
[data-slot="input-group"]:has(textarea) { align-items:flex-end; flex-wrap:wrap; border-radius:var(--r-card); padding:var(--s-3); }
[data-slot="input-group"] [data-slot="input-group-textarea"] { min-width:0; width:100%; min-height:96px; max-height:320px; flex:1 0 100%; padding:var(--s-2); background:transparent; box-shadow:none; border-radius:var(--r-sm); }
[data-slot="input-group"]:has(textarea) > [data-slot="input-group-button"] { margin-inline-start:auto; }
[data-slot="input-group"] [data-slot="input-group-textarea"]:focus { box-shadow:none; }
@media (max-width: 640px) {
  [data-slot="input-group"] { flex-wrap:wrap; }
  [data-slot="input-group"] [data-slot="input-group-input"] { flex-basis:100px; }
}

[data-slot="input-search-disk"] .v-icon { width: 20px; height: 20px; stroke-width: 2; }

}
